Drag the slider on any recipe to scale the ingredient amounts up or down.
Recipes from other people’s own kitchens or family archives are shown in full. Recipes from commercial publications aren’t reproduced here out of respect for the original publishers – a link to the source is always given instead. Those ones are password protected purely so I can still pull them up easily myself when I’m cooking.
viewof recipe_unlock_form = {
  const input = html`&lt;input type="password" placeholder="Password for protected recipes"&gt;`;
  const btn = html`&lt;button&gt;Unlock&lt;/button&gt;`;
  const err = html`&lt;span style="color:#b00020; margin-left:0.5em;"&gt;&lt;/span&gt;`;
  const b64ToBytes = b64 =&gt; Uint8Array.from(atob(b64), c =&gt; c.charCodeAt(0));
  const tryUnlock = async () =&gt; {
    err.textContent = "";
    try {
      const enc = await fetch("protected_recipes.json").then(r =&gt; r.json());
      const passKey = await crypto.subtle.importKey(
        "raw", new TextEncoder().encode(input.value), "PBKDF2", false, ["deriveKey"]
      );
      const key = await crypto.subtle.deriveKey(
        {name: "PBKDF2", salt: b64ToBytes(enc.salt), iterations: enc.iterations, hash: "SHA-256"},
        passKey, {name: "AES-CBC", length: 256}, false, ["decrypt"]
      );
      const plainBuf = await crypto.subtle.decrypt(
        {name: "AES-CBC", iv: b64ToBytes(enc.iv)}, key, b64ToBytes(enc.ciphertext)
      );
      const data = JSON.parse(new TextDecoder().decode(plainBuf));
      sessionStorage.setItem("recipesUnlocked", "1");
      sessionStorage.setItem("recipesData", JSON.stringify(data));
      location.reload();
    } catch (e) {
      err.textContent = "Incorrect password.";
    }
  };
  btn.onclick = tryUnlock;
  input.addEventListener("keydown", e =&gt; { if (e.key === "Enter") tryUnlock(); });
  return html`&lt;span&gt;${input} ${btn}${err}&lt;/span&gt;`;
}
recipe_unlocked = sessionStorage.getItem("recipesUnlocked") === "1"
protected_recipe_data = recipe_unlocked ? JSON.parse(sessionStorage.getItem("recipesData")) : null

Nana’s Devil Food Cake
Recipe from Family recipe, via r/Old_Recipes
Base recipe serves 12.

viewof nanas_devil_food_cake_servings = Inputs.range(
  [1, 24], {value: 12, step: 1, label: "Servings"}
)







nanas_devil_food_cake_base = ({
  servings: 12,
  ingredients: [{"name":"Flour","amount":2,"unit":"cups"},{"name":"Salt","amount":1,"unit":"tsp"},{"name":"Baking powder","amount":1,"unit":"tsp"},{"name":"Baking soda","amount":2,"unit":"tsp"},{"name":"Cocoa","amount":0.75,"unit":"cup"},{"name":"Sugar","amount":2,"unit":"cups"},{"name":"Oil","amount":1,"unit":"cup"},{"name":"Milk","amount":1,"unit":"cup"},{"name":"Coffee, cooled but not cold","amount":1,"unit":"cup"},{"name":"Eggs","amount":2,"unit":""},{"name":"Vanilla","amount":1,"unit":"tsp"}]
})







nanas_devil_food_cake_scaled = {
  const ratio = nanas_devil_food_cake_servings / nanas_devil_food_cake_base.servings;
  return nanas_devil_food_cake_base.ingredients.map(i =&gt; ({
    Ingredient: i.name,
    Amount: Math.round(i.amount * ratio * 100) / 100,
    Unit: i.unit
  }));
}







Inputs.table(nanas_devil_food_cake_scaled, {columns: ["Ingredient", "Amount", "Unit"]})






Sift the flour, salt, baking powder, baking soda and cocoa together. In a separate bowl whisk the sugar, oil, milk, cooled coffee, eggs and vanilla until smooth. Slowly fold the dry ingredients into the wet ingredients until just combined. Pour into a greased and floured pan and bake at around 190°C (375°F) until a skewer comes out clean – baking time varies quite a bit depending on the pan, so start checking early.

